import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.02.24 (2)
 */
public abstract class Animal extends LivingBeing
{
    private static final Random rand = Randomizer.getRandom();

    private enum Sex { MALE, FEMALE }

    private final Sex sex;
    private final AnimalProfile profile;
    private int age;
    private int foodLevel;

    protected static final class FoodValue
    {
        private final Class<? extends LivingBeing> type;
        private final int value;

        private FoodValue(Class<? extends LivingBeing> type, int value)
        {
            this.type = type;
            this.value = value;
        }
    }

    protected static final class AnimalProfile
    {
        private final int maxAge;
        private final int initialFoodLevel;
        private final int newbornFoodLevel;
        private final boolean activeAtNight;
        private final int breedingAge;
        private final double breedingProbability;
        private final int maxLitterSize;
        private final Map<Class<? extends LivingBeing>, Integer> foodValues;

        private AnimalProfile(int maxAge, int initialFoodLevel, int newbornFoodLevel,
                              boolean activeAtNight, int breedingAge,
                              double breedingProbability, int maxLitterSize,
                              Map<Class<? extends LivingBeing>, Integer> foodValues)
        {
            this.maxAge = maxAge;
            this.initialFoodLevel = initialFoodLevel;
            this.newbornFoodLevel = newbornFoodLevel;
            this.activeAtNight = activeAtNight;
            this.breedingAge = breedingAge;
            this.breedingProbability = breedingProbability;
            this.maxLitterSize = maxLitterSize;
            this.foodValues = foodValues;
        }
    }

    /**
     * Create a new animal at location in field.
     * @param randomAge If true, the animal will have random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param profile The species-specific lifecycle configuration.
     */
    public Animal(boolean randomAge, Field field, Location location, AnimalProfile profile)
    {
        super(field, location);
        this.profile = profile;
        sex = randomSex();

        if(randomAge) {
            age = rand.nextInt(profile.maxAge);
            foodLevel = rand.nextInt(profile.initialFoodLevel);
        }
        else {
            age = 0;
            foodLevel = profile.newbornFoodLevel;
        }
    }

    private Sex randomSex()
    {
        Sex[] values = Sex.values();
        return values[rand.nextInt(values.length)];
    }

    protected static FoodValue food(Class<? extends LivingBeing> type, int value)
    {
        return new FoodValue(type, value);
    }

    private static Map<Class<? extends LivingBeing>, Integer> foodValues(FoodValue... values)
    {
        Map<Class<? extends LivingBeing>, Integer> foods = new LinkedHashMap<>();
        for(FoodValue value : values) {
            foods.put(value.type, value.value);
        }
        return Collections.unmodifiableMap(foods);
    }

    protected static AnimalProfile profile(int maxAge, int initialFoodLevel,
                                           int newbornFoodLevel, boolean activeAtNight,
                                           int breedingAge, double breedingProbability,
                                           int maxLitterSize, FoodValue... foods)
    {
        return new AnimalProfile(maxAge, initialFoodLevel, newbornFoodLevel,
                                 activeAtNight, breedingAge, breedingProbability,
                                 maxLitterSize, foodValues(foods));
    }

    /**
     * Run the standard animal lifecycle for one simulation step.
     * @param newAnimals A list to receive newly born animals.
     */
    private void live(List<LivingBeing> newAnimals)
    {
        incrementAge();
        incrementHunger();

        if(isNight() != profile.activeAtNight || !isAlive()) {
            return;
        }

        giveBirth(newAnimals);

        Location newLocation = findFood();
        if(newLocation == null && getLocation() != null) {
            newLocation = getField().freeAdjacentLocation(getLocation());
        }

        if(newLocation != null) {
            setLocation(newLocation);
        }
    }

    private void incrementAge()
    {
        age++;
        if(age > profile.maxAge) {
            setDead();
        }
    }

    private void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    private Location findFood()
    {
        Field field = getField();
        if(field == null || getLocation() == null) {
            return null;
        }

        for(Location where : field.adjacentLocations(getLocation())) {
            LivingBeing occupant = field.getLivingBeingAt(where);
            for(Map.Entry<Class<? extends LivingBeing>, Integer> food :
                    profile.foodValues.entrySet()) {
                if(food.getKey().isInstance(occupant)) {
                    if(occupant.isAlive()) {
                        occupant.setDead();
                        foodLevel += food.getValue();
                        return where;
                    }
                }
            }
        }
        return null;
    }

    private void giveBirth(List<LivingBeing> newAnimals)
    {
        Field field = getField();
        if(field == null || getLocation() == null || !canBreed()) {
            return;
        }

        for(Location where : field.adjacentLocations(getLocation())) {
            LivingBeing occupant = field.getLivingBeingAt(where);
            if(getClass().isInstance(occupant) && hasOppositeSex((Animal) occupant)) {
                List<Location> free = field.getFreeAdjacentLocations(getLocation());
                int births = breed();
                for(int b = 0; b < births && free.size() > 0; b++) {
                    Location loc = free.remove(0);
                    newAnimals.add(createOffspring(field, loc));
                }
            }
        }
    }

    private boolean hasOppositeSex(Animal other)
    {
        return sex != other.sex;
    }

    private int breed()
    {
        if(rand.nextDouble() <= profile.breedingProbability) {
            return rand.nextInt(profile.maxLitterSize) + 1;
        }
        return 0;
    }

    private boolean canBreed()
    {
        return age >= profile.breedingAge;
    }

    /**
     * Create a newborn of this animal's species.
     * @param field The field the newborn will occupy.
     * @param location The newborn's location.
     * @return The newborn animal.
     */
    protected abstract Animal createOffspring(Field field, Location location);

    /**
     * Act for one simulation step.
     * @param newAnimals A list to receive newly born animals.
     */
    @Override
    public final void act(List<LivingBeing> newAnimals)
    {
        live(newAnimals);
    }

}

import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Random;

/**
 * Represent a rectangular grid of field positions.
 * Each position is able to store a single living being.
 *
 * @version 2016.02.29
 */
public class Field
{
    // A random number generator for providing random locations.
    private static final Random rand = Randomizer.getRandom();

    private final int depth;
    private final int width;
    // Storage for living beings.
    private final LivingBeing[][] field;

    /**
     * Represent a field of the given dimensions.
     * @param depth The depth of the field.
     * @param width The width of the field.
     */
    public Field(int depth, int width)
    {
        this.depth = depth;
        this.width = width;
        field = new LivingBeing[depth][width];
    }

    /**
     * Empty the field.
     */
    public void clear()
    {
        for(int row = 0; row < depth; row++) {
            for(int col = 0; col < width; col++) {
                field[row][col] = null;
            }
        }
    }

    /**
     * Clear the given location.
     * @param location The location to clear.
     */
    public void clear(Location location)
    {
        field[location.getRow()][location.getCol()] = null;
    }

    /**
     * Place a living being at the given location.
     * If there is already a living being at the location it will
     * be lost.
     * @param being The living being to be placed.
     * @param row Row coordinate of the location.
     * @param col Column coordinate of the location.
     */
    public void place(LivingBeing being, int row, int col)
    {
        place(being, new Location(row, col));
    }

    /**
     * Place a living being at the given location.
     * If there is already a living being at the location it will
     * be lost.
     * @param being The living being to be placed.
     * @param location Where to place the living being.
     */
    public void place(LivingBeing being, Location location)
    {
        field[location.getRow()][location.getCol()] = being;
    }

    /**
     * Return the living being at the given location, if any.
     * @param location Where in the field.
     * @return The living being at the given location, or null if there is none.
     */
    public LivingBeing getLivingBeingAt(Location location)
    {
        return getLivingBeingAt(location.getRow(), location.getCol());
    }

    /**
     * Return the living being at the given location, if any.
     * @param row The desired row.
     * @param col The desired column.
     * @return The living being at the given location, or null if there is none.
     */
    public LivingBeing getLivingBeingAt(int row, int col)
    {
        return field[row][col];
    }

    /**
     * Generate a random location that is adjacent to the
     * given location, or is the same location.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location randomAdjacentLocation(Location location)
    {
        List<Location> adjacent = adjacentLocations(location);
        return adjacent.get(0);
    }

    /**
     * Get a shuffled list of the free adjacent locations.
     * @param location Get locations adjacent to this.
     * @return A list of free adjacent locations.
     */
    public List<Location> getFreeAdjacentLocations(Location location)
    {
        List<Location> free = new LinkedList<>();
        List<Location> adjacent = adjacentLocations(location);
        for(Location next : adjacent) {
            if(getLivingBeingAt(next) == null) {
                free.add(next);
            }
        }
        return free;
    }

    /**
     * Try to find a free location that is adjacent to the
     * given location. If there is none, return null.
     * The returned location will be within the valid bounds
     * of the field.
     * @param location The location from which to generate an adjacency.
     * @return A valid location within the grid area.
     */
    public Location freeAdjacentLocation(Location location)
    {
        // The available free ones.
        List<Location> free = getFreeAdjacentLocations(location);
        if(free.size() > 0) {
            return free.get(0);
        }
        else {
            return null;
        }
    }

    /**
     * Return a shuffled list of locations adjacent to the given one.
     * The list will not include the location itself.
     * All locations will lie within the grid.
     * @param location The location from which to generate adjacencies.
     * @return A list of locations adjacent to that given.
     */
    public List<Location> adjacentLocations(Location location)
    {
        assert location != null : "Null location passed to adjacentLocations";
        // The list of locations to be returned.
        List<Location> locations = new LinkedList<>();
        if(location != null) {
            int row = location.getRow();
            int col = location.getCol();
            for(int roffset = -1; roffset <= 1; roffset++) {
                int nextRow = row + roffset;
                if(nextRow >= 0 && nextRow < depth) {
                    for(int coffset = -1; coffset <= 1; coffset++) {
                        int nextCol = col + coffset;
                        // Exclude invalid locations and the original location.
                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
                            locations.add(new Location(nextRow, nextCol));
                        }
                    }
                }
            }

            // Shuffle the list. Several other methods rely on the list
            // being in a random order.
            Collections.shuffle(locations, rand);
        }
        return locations;
    }

    /**
     * Return the depth of the field.
     * @return The depth of the field.
     */
    public int getDepth()
    {
        return depth;
    }

    /**
     * Return the width of the field.
     * @return The width of the field.
     */
    public int getWidth()
    {
        return width;
    }
}

import java.util.List;
import java.util.Random;

/**
 * Plants do not move around but they do grow and produce more plants. 
 * They have a max age that if they reach, they will die. 
 * They will also die if eaten by either Hedgehogs or Frogs. 
 * Their growth is controlled by the probability that it rains. 
 * Plants produce more seeds when it is day time.
 *
 * @version 2022.02.24
 */
public class Plant extends LivingBeing
{
    // The plant's age
    private int age;
    //The probability that the plant can grow
    private static final double GROWING_PROBABILITY = 0.35;
    //The probability that it will rain, affects growth
    private static final double RAIN_PROBABILITY = 0.25;

    //The plant can only produce new plants if it is ripe
    private static final int RIPE_AGE = 3;
    //Maximum age of a plant
    private static final int MAX_AGE = 10000;
    //Maximum number of plants a plant can create
    private static final int MAX_NEW_PLANTS = 10;

    private static final Random rand = Randomizer.getRandom();

    /**
     * Constructor for objects of class Plant
     * @param randomAge If true, the plant will have random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plant(boolean randomAge, Field field, Location location)
    {
        // initialise instance variables
        super(field,location);
        if(randomAge) {
            age = rand.nextInt(MAX_AGE);
        }
        else {
            age = 0;
        }
    }

    /**
     * What plants will do day to day, they do not move around, just increase in age and
     * make new plants
     * @param newPlants A list to return newly born plants
     */
    @Override
    public void act(List<LivingBeing> newPlants) {
        incrementAge();
        if(isAlive()) {
            makeNewPlants(newPlants);
        }
    }

    /**
     * Check if new plants will be created
     * @param newPlants A list to return newly made plants
     */
    private void makeNewPlants(List<LivingBeing> newPlants) {
        //gets adjacent locations and populates it if it can give birth
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = grow();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Plant p = new Plant(false, field, loc);
            newPlants.add(p);
        }
    }

    /**
     * Decides how many new plants we want. Depends on the probability that a new plant can grow
     * and the probability that it is raining
     * @return The number of new plants made (may be zero)
     */
    private int grow() {
        int numOfNewPlants = 0;
        if(rand.nextDouble() <= GROWING_PROBABILITY) {
            if(canDisperseSeeds() && rand.nextDouble() <= RAIN_PROBABILITY) {
                if(isNight()) {
                    numOfNewPlants = rand.nextInt(MAX_NEW_PLANTS) + 1; //Plants will only grow if it rains
                } else{
                    numOfNewPlants = rand.nextInt(MAX_NEW_PLANTS) + 2; //More new plants created in day time
                }
            } else {
                numOfNewPlants = 0; 
            }
        }
        return numOfNewPlants;
    }

    /**
     * A Plant can only disperse if it is ripe
     */
    private boolean canDisperseSeeds() {
        return age >= RIPE_AGE;
    }

    /**
     * Increase the age.
     * This could result in the plant's death.
     */
    private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }
}
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * This class collects and provides some statistical data on the state 
 * of a field. It is flexible: it will create and maintain a counter 
 * for any class of object that is found within the field.
 *
 * @version 2016.02.29
 */
public class FieldStats
{
    // Counters for each type of entity in the simulation.
    private final Map<Class<?>, Counter> counters;
    // Whether the counters are currently up to date.
    private boolean countsValid;

    /**
     * Construct a FieldStats object.
     */
    public FieldStats()
    {
        // Set up a collection for counters for each type of living being found.
        counters = new LinkedHashMap<>();
        countsValid = true;
    }

    /**
     * Get details of what is in the field.
     * @return A string describing what is in the field.
     */
    public String getPopulationDetails(Field field)
    {
        StringBuilder buffer = new StringBuilder();
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class<?> key : counters.keySet()) {
            Counter info = counters.get(key);
            buffer.append(info.getName());
            buffer.append(": ");
            buffer.append(info.getCount());
            buffer.append(' ');
        }
        return buffer.toString();
    }

    /**
     * Invalidate the current set of statistics; reset all 
     * counts to zero.
     */
    public void reset()
    {
        countsValid = false;
        for(Class<?> key : counters.keySet()) {
            Counter count = counters.get(key);
            count.reset();
        }
    }

    /**
     * Increment the count for one class of living being.
     * @param beingClass The class of living being to increment.
     */
    public void incrementCount(Class<?> beingClass)
    {
        Counter count = counters.get(beingClass);
        if(count == null) {
            count = new Counter(beingClass.getName());
            counters.put(beingClass, count);
        }
        count.increment();
    }

    /**
     * Indicate that counting has been completed.
     */
    public void countFinished()
    {
        countsValid = true;
    }

    /**
     * Determine whether the simulation is still viable.
     * I.e., should it continue to run.
     * @return true If there is more than one species alive.
     */
    public boolean isViable(Field field)
    {
        // How many counts are non-zero.
        int nonZero = 0;
        if(!countsValid) {
            generateCounts(field);
        }
        for(Class<?> key : counters.keySet()) {
            Counter info = counters.get(key);
            if(info.getCount() > 0) {
                nonZero++;
            }
        }
        return nonZero > 1;
    }

    /**
     * Generate counts of the number of living beings.
     * These are not kept up to date as living beings
     * are placed in the field, but only when a request
     * is made for the information.
     * @param field The field to generate the stats for.
     */
    private void generateCounts(Field field)
    {
        reset();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                LivingBeing being = field.getLivingBeingAt(row, col);
                if(being != null) {
                    incrementCount(being.getClass());
                }
            }
        }
        countsValid = true;
    }
}

